const PostSchema = z.object({
  title: z.string().min(1), body: z.string(), published: z.boolean(),
})

export const usePosts = () =>
  useQuery({ queryKey: ['posts'], queryFn: () => fetch('/api/posts').then(json) })

export function useCreatePost() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (data: z.infer<typeof PostSchema>) =>
      fetch('/api/posts', { method: 'POST', body: JSON.stringify(data) }).then(json),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['posts'] }),
  })
}
// …usePost, useUpdatePost, useDeletePost

function NewPost() {
  const create = useCreatePost()
  const { register, handleSubmit, formState: { errors } } = useForm({
    resolver: zodResolver(PostSchema),
    defaultValues: { title: '', body: '', published: false },
  })
  return (
    <form onSubmit={handleSubmit((v) => create.mutate(v))}>
      <input {...register('title')} />
      {errors.title && <p>{errors.title.message}</p>}
      <textarea {...register('body')} />
      <input type="checkbox" {...register('published')} />
      <button disabled={create.isPending}>Create</button>
    </form>
  )
}

