import { defineFeature } from '@pyreon/feature'
import { z } from 'zod'

export const Posts = defineFeature({
  name: 'posts',
  api: '/api/posts',
  schema: z.object({
    title: z.string().min(1), body: z.string(), published: z.boolean(),
  }),
})

const NewPost = () => {
  const form = Posts.useForm()   // POST /api/posts, then the list refetches
  return (
    <form onSubmit={form.handleSubmit}>
      <Posts.Field form={form} name="title" />
      <Posts.Field form={form} name="body" />
      <Posts.Field form={form} name="published" />
      <button disabled={() => form.isSubmitting()}>Create</button>
    </form>
  )
}

