const PostsAdmin = () => {
  const term = signal('')
  const all = Posts.useList()
  const found = Posts.useSearch(term)
  const remove = Posts.useDelete()
  const rows = () => (term() ? found.data() : all.data()) ?? []
  const view = Posts.useTable(rows, { columns: ['title', 'published'] })
  return (
    <>
      <input placeholder="Search" onInput={(e) => term.set(e.currentTarget.value)} />
      <Posts.Table
        of={view}
        cell={{
          title: (ctx) => (
            <>
              {ctx.row.title}
              <button onClick={() => remove.mutate((ctx.row as typeof ctx.row & { id: number }).id)}>Delete</button>
            </>
          ),
        }}
        empty="No posts yet"
      />
    </>
  )
}

const EditPost = (props: { id: number }) => {
  const form = Posts.useForm({
    mode: 'edit',
    id: props.id,
    onSuccess: () => toast.success('Saved'),
  })
  return (
    <Show when={() => !form.isLoading()} fallback={<p>Loading…</p>}>
      <form onSubmit={form.handleSubmit}>
        <Posts.Field form={form} name="title" />
        <Posts.Field form={form} name="body" />
        <button disabled={() => form.isSubmitting()}>Save</button>
      </form>
    </Show>
  )
}
